import { pool } from './db.mjs';

/**
 * Writes German, French and Italian text for every listing.
 *
 *   node scripts/translate-listings.mjs [--dry] [--limit N]
 *
 * 1,336 listings existed in English and one existed in German. The directory
 * was therefore empty in three of the four languages the site ships — including
 * the one the whole content strategy is built around, where fourteen guides
 * point at a directory that returns nothing.
 *
 * Not machine translation. Every one of these descriptions was generated by a
 * template this repository owns, so the honest fix is to write that template in
 * each language and run it again. The German reads as German rather than as
 * English put through a translator, and the facts are identical by construction
 * because they come from the same columns.
 *
 * The source is derived from the English text rather than from which import
 * touched a row last: 247 listings were seeded from a licensing register and
 * later enriched from Google Maps, and keying off coordinates would have given
 * those a German description that contradicted their English one.
 *
 * Category names come from category_translations — the site's own taxonomy,
 * already translated — rather than from Google's sixty English labels.
 */

const DRY = process.argv.includes('--dry');
const limitArg = process.argv.indexOf('--limit');
const LIMIT = limitArg > -1 ? Number(process.argv[limitArg + 1]) : Infinity;

const LOCALES = ['de', 'fr', 'it'];

const COUNTRY = {
  de: { TZ: 'Tansania', KE: 'Kenia', UG: 'Uganda', RW: 'Ruanda' },
  fr: { TZ: 'Tanzanie', KE: 'Kenya', UG: 'Ouganda', RW: 'Rwanda' },
  it: { TZ: 'Tanzania', KE: 'Kenya', UG: 'Uganda', RW: 'Ruanda' },
};

/** KATO publishes grades as "Category A" … "Category E" and "Associate Member". */
const GRADE = {
  de: (g) => (g === 'Associate Member' ? 'assoziiertes Mitglied' : `Mitglied der ${g.replace('Category', 'Kategorie')}`),
  fr: (g) => (g === 'Associate Member' ? 'membre associé' : `membre de ${g.replace('Category', 'catégorie')}`),
  it: (g) => (g === 'Associate Member' ? 'membro associato' : `membro di ${g.replace('Category', 'categoria')}`),
};

const TEMPLATES = {
  // Structured as labelled values rather than a sentence built around the
  // category name. "ist in Google Maps als safaris & reiseveranstalter
  // eingetragen" was wrong twice over: German capitalises nouns, and a plural
  // category forced into a singular clause reads like a translation. A label
  // and a value sidesteps the grammar entirely and stays readable when the
  // category is "Restaurants & Food Experiences".
  gmaps: {
    de: (b) => ({
      tagline: `${b.category} in ${[b.city, b.country].filter(Boolean).join(', ')}`,
      description:
        `${b.name}${b.city ? ` in ${b.city}` : ''}, ${b.country}. Kategorie: ${b.category}.` +
        `${b.address ? ` Adresse laut Google Maps: ${b.address}.` : ''} Dieser Eintrag wurde aus ` +
        `öffentlichen Kartendaten erstellt und bisher nicht vom Unternehmen übernommen; die Angaben ` +
        `sind daher nicht bestätigt.`,
    }),
    fr: (b) => ({
      tagline: `${b.category} à ${[b.city, b.country].filter(Boolean).join(', ')}`,
      description:
        `${b.name}${b.city ? `, à ${b.city}` : ''}, ${b.country}. Catégorie : ${b.category}.` +
        `${b.address ? ` Adresse indiquée sur Google Maps : ${b.address}.` : ''} Cette fiche a été ` +
        `constituée à partir de données cartographiques publiques et n’a pas encore été revendiquée ` +
        `par l’entreprise ; ses informations ne sont donc pas confirmées.`,
    }),
    it: (b) => ({
      tagline: `${b.category} a ${[b.city, b.country].filter(Boolean).join(', ')}`,
      description:
        `${b.name}${b.city ? `, a ${b.city}` : ''}, ${b.country}. Categoria: ${b.category}.` +
        `${b.address ? ` Indirizzo secondo Google Maps: ${b.address}.` : ''} Questa scheda è stata ` +
        `creata da dati cartografici pubblici e non è ancora stata rivendicata dall’attività; i dati ` +
        `non sono quindi confermati.`,
    }),
  },

  kato: {
    de: (b) => ({
      tagline: `${b.grade ? GRADE.de(b.grade) : 'Mitglied'}, Verband kenianischer Reiseveranstalter`,
      description:
        `${b.name} ist ein Reiseveranstalter in Kenia und im Verband kenianischer Reiseveranstalter ` +
        `(KATO) als ${b.grade ? GRADE.de(b.grade) : 'Mitglied'} geführt. Dieser Eintrag stammt aus ` +
        `dem öffentlichen Mitgliederverzeichnis von KATO und wurde bisher nicht vom Unternehmen ` +
        `übernommen, enthält also nichts über dieses Register hinaus.`,
    }),
    fr: (b) => ({
      tagline: `${b.grade ? GRADE.fr(b.grade) : 'Membre'}, Association des tour-opérateurs du Kenya`,
      description:
        `${b.name} est un tour-opérateur au Kenya, inscrit comme ${b.grade ? GRADE.fr(b.grade) : 'membre'} ` +
        `à l’Association des tour-opérateurs du Kenya (KATO). Cette fiche provient du répertoire public ` +
        `des membres de KATO et n’a pas encore été revendiquée par l’entreprise ; elle ne contient donc ` +
        `rien au-delà de ce registre.`,
    }),
    it: (b) => ({
      tagline: `${b.grade ? GRADE.it(b.grade) : 'Membro'}, Associazione dei tour operator del Kenya`,
      description:
        `${b.name} è un tour operator in Kenya, iscritto come ${b.grade ? GRADE.it(b.grade) : 'membro'} ` +
        `all’Associazione dei tour operator del Kenya (KATO). Questa scheda proviene dall’elenco pubblico ` +
        `dei soci KATO e non è ancora stata rivendicata dall’attività, quindi non contiene nulla oltre a ` +
        `quel registro.`,
    }),
  },

  utb: {
    de: (b) => ({
      tagline: 'Lizenziert vom Uganda Tourism Board',
      description:
        `${b.name} besitzt die Lizenz ${b.licence} des Uganda Tourism Board. Dieser Eintrag stammt aus ` +
        `dem öffentlichen Lizenzregister der Behörde und wurde bisher nicht vom Unternehmen übernommen, ` +
        `enthält also nichts über dieses Register hinaus.`,
    }),
    fr: (b) => ({
      tagline: 'Licencié par l’Office du tourisme de l’Ouganda',
      description:
        `${b.name} détient la licence ${b.licence} de l’Office du tourisme de l’Ouganda. Cette fiche ` +
        `provient du registre public des opérateurs licenciés et n’a pas encore été revendiquée par ` +
        `l’entreprise ; elle ne contient donc rien au-delà de ce registre.`,
    }),
    it: (b) => ({
      tagline: 'Autorizzato dall’Ente del turismo dell’Uganda',
      description:
        `${b.name} è titolare della licenza ${b.licence} dell’Ente del turismo dell’Uganda. Questa ` +
        `scheda proviene dal registro pubblico degli operatori autorizzati e non è ancora stata ` +
        `rivendicata dall’attività, quindi non contiene nulla oltre a quel registro.`,
    }),
  },
};

/** Which generator wrote the English, so the translation says the same thing. */
function sourceOf(englishDescription = '') {
  if (/Kenya Association of Tour Operators/i.test(englishDescription)) return 'kato';
  if (/Uganda Tourism Board licence/i.test(englishDescription)) return 'utb';
  if (/listed on Google Maps/i.test(englishDescription)) return 'gmaps';
  return null;
}

/** "Category A member, Kenya Association…" -> "Category A" */
function gradeFrom(englishTagline = '') {
  if (/^Associate Member/i.test(englishTagline)) return 'Associate Member';
  const m = englishTagline.match(/^(Category [A-E])/i);
  return m ? m[1] : null;
}

const client = await pool.connect();

try {
  const { rows: catNames } = await client.query(
    `select c.id, ct.locale, ct.name
       from categories c join category_translations ct on ct.category_id = c.id`,
  );
  const categoryName = new Map(catNames.map((c) => [`${c.id}:${c.locale}`, c.name]));

  const { rows: listings } = await client.query(
    `select b.id, b.name, b.city, b.address, b.country_code, b.license_number,
            en.tagline as en_tagline, en.description as en_description,
            (select bc.category_id from business_categories bc
              where bc.business_id = b.id and bc.is_primary limit 1) as category_id
       from businesses b
       join business_translations en on en.business_id = b.id and en.locale = 'en'
      where b.status = 'approved' and b.deleted_at is null
      order by b.name`,
  );

  const work = listings.slice(0, LIMIT);
  console.log(`\n  ${work.length} listings\n`);

  const stats = { written: 0, skipped: 0, bySource: {} };

  for (const b of work) {
    const source = sourceOf(b.en_description ?? '');
    if (!source) {
      // A listing an operator wrote themselves. Their words are not ours to
      // translate from a template.
      stats.skipped++;
      continue;
    }
    stats.bySource[source] = (stats.bySource[source] ?? 0) + 1;

    for (const locale of LOCALES) {
      const country = COUNTRY[locale][b.country_code] ?? b.country_code ?? '';
      const category =
        categoryName.get(`${b.category_id}:${locale}`) ??
        categoryName.get(`${b.category_id}:en`) ??
        '';

      const built = TEMPLATES[source][locale]({
        name: b.name,
        city: b.city,
        address: b.address,
        country,
        category,
        grade: gradeFrom(b.en_tagline ?? ''),
        licence: b.license_number,
      });

      if (DRY) continue;

      await client.query(
        `insert into business_translations
           (business_id, locale, tagline, short_description, description)
         values ($1,$2,$3,$3,$4)
         on conflict (business_id, locale) do update
           set tagline = excluded.tagline,
               short_description = excluded.short_description,
               description = excluded.description`,
        [b.id, locale, built.tagline, built.description],
      );
    }

    stats.written++;
    if (stats.written % 200 === 0) console.log(`  ${stats.written} translated`);
  }

  console.log(`\n  listings translated  ${stats.written}`);
  console.log(`  skipped (own words)  ${stats.skipped}`);
  console.log(`  by source            ${JSON.stringify(stats.bySource)}`);
  if (DRY) console.log('\n  DRY RUN — nothing written\n');
} catch (err) {
  console.error('\n  Failed:', err.message);
  process.exitCode = 1;
} finally {
  client.release();
  await pool.end();
}
